{
  "findings": [
    {
      "check_id": "CKV_GCP_102",
      "title": "Cloud Run service is publicly accessible",
      "resource": "google_cloud_run_service_iam_binding.search_service_public",
      "severity": "MEDIUM",
      "explanation": "The roles/run.invoker binding grants access to allUsers, allowing unauthenticated users on the internet to invoke the Cloud Run service."
    }
  ],
  "patched_code": "variable "search_service_invoker_members" {
  description = "Authenticated IAM principals permitted to invoke the search Cloud Run service."
  type        = list(string)

  validation {
    condition = (
      length(var.search_service_invoker_members) > 0 &&
      alltrue([
        for member in var.search_service_invoker_members :
        !contains(["allUsers", "allAuthenticatedUsers"], member)
      ])
    )
    error_message = "At least one authenticated principal must be provided; allUsers and allAuthenticatedUsers are prohibited."
  }
}

resource "google_cloud_run_service_iam_binding" "search_service_public" {
  location = google_cloud_run_service.search_service.location
  project  = google_cloud_run_service.search_service.project
  service  = google_cloud_run_service.search_service.name
  role     = "roles/run.invoker"
  members  = var.search_service_invoker_members
}
",
  "fix_summary": "Replaced the public allUsers grant with a required list of explicitly authorized IAM principals. Added validation preventing public or broadly authenticated access."
}
